import Foundation
import XCTest
@testable import BridgeyMac

/// A session recorded between two Bridgey session clients (rust/client, the core of the Windows app): the link the
/// Windows side sends passes the Mac's own link checks and sequence rule, and every frame is tagged by its sender.
/// Generated by rust/client/src/vectors.rs.
final class SessionClientQuickVectorTests: XCTestCase {
    func testTheWindowsLinkPassesTheMacsChecks() throws {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .appendingPathComponent("../../../protocol/test-vectors/session-client-quick-v1.json").standardizedFileURL
        let object = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        let key = try XCTUnwrap(Data(base64Encoded: try XCTUnwrap(object["sessionKey"] as? String)))
        var ids: [String: String] = [:]
        var frames: [(String, PairingMessage)] = []
        for raw in try XCTUnwrap(object["frames"] as? [[String: Any]]) {
            let message = try decodeProtocolMessage(Data(try XCTUnwrap(raw["line"] as? String).utf8))
            let from = try XCTUnwrap(raw["from"] as? String)
            if message.kind == "pairing.offer" || message.kind == "pairing.answer" { ids[from] = message.deviceId }
            frames.append((from, message))
        }
        let envelopeKey = SessionSecurity.envelopeKey(sessionKey: key)
        var sequence = QuickRequestSequence()
        var checked = false
        for (from, message) in frames where !message.kind.hasPrefix("pairing.") {
            XCTAssertTrue(SessionSecurity.tagMatches(envelopeKey: envelopeKey, senderDeviceID: try XCTUnwrap(ids[from]), message: message), message.kind)
            guard from == "initiator", message.kind == "quick.request" else { continue }
            let plaintext = try decrypt(nonce: try XCTUnwrap(message.nonce), ciphertext: try XCTUnwrap(message.ciphertext), key: key)
            let payload = try XCTUnwrap(try JSONSerialization.jsonObject(with: plaintext) as? [String: Any])
            XCTAssertEqual(validatedWebLink(try XCTUnwrap(payload["value"] as? String)), object["linkToPhone"] as? String)
            XCTAssertTrue(sequence.accept(feature: try XCTUnwrap(payload["feature"] as? String), sequence: try XCTUnwrap(payload["sequence"] as? Int)))
            checked = true
        }
        XCTAssertTrue(checked)
    }
}
